DO $$ DECLARE d text;BEGIN d:=pg_get_functiondef('core.guard_active_private_domain_write()'::regprocedure);d:=regexp_replace(d,'\mBEGIN\M','BEGIN IF current_user=''migration_owner'' AND TG_TABLE_SCHEMA=''ops'' AND TG_TABLE_NAME IN (''import_batch'',''import_row'') AND current_setting(''ops.expiring_imports'',true)=''yes'' THEN RETURN NEW;END IF;');EXECUTE d;END $$;
CREATE FUNCTION ops.guard_restore_map() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF current_user='app_domain' AND NOT EXISTS(SELECT 1 FROM ops.restore_run r JOIN core.command_receipt c ON c.id=r.command_receipt_id AND c.workspace_id=r.workspace_id WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.restore_run_id AND r.state='previewed' AND c.command_type='portability.preview' AND c.state='claimed') THEN RAISE EXCEPTION 'owned preview mapping required';END IF;RETURN NEW;END $$;
CREATE TRIGGER restore_map_guard BEFORE INSERT ON ops.restore_id_map FOR EACH ROW EXECUTE FUNCTION ops.guard_restore_map();REVOKE ALL ON FUNCTION ops.guard_restore_map() FROM PUBLIC;
